-- GENERATED by `wfj generate` from data/gossip/gossip-14.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["1400f25964c456a3"] = { "Accidenti, ci sono 3 gradi Kraklenheit. Continua a cercare.", "." },
  ["140465a0a82954e3"] = { "Salute, <signore/signorina>. Sono Nyrill, apprendista del maestro Xylem. Se hai qualche questione, non esitare a parlarne con il maestro.\n\nSarò qui al tuo servizio quando vorrai tornare ai piedi della montagna.", "." },
  ["1409675888b9021e"] = { "Piacere di conoscerti.", "." },
  ["140bf47189880464"] = { "%s costringe uno dei suoi servitori ⟦Firesworn=Fedele del Fuoco⟧ a esplodere!", "." },
  ["1417aa370bfa4666"] = { "In tutta Azeroth ci sono spedizioni che spariscono. Se ne trovi qualcuna, mi faresti un favore riportandomela.", "." },
  ["141b729f3618d5d0"] = { "È un po' danneggiato, ma dovrei comunque riuscire a ricavarne delle buone informazioni.", "." },
  ["1422a3d6cc1fc075"] = { "Non dovreste essere qui! Uccideteli!", "." },
  ["142517aac9561a3f"] = { "OH NOOO!! TORNO SUBITO IN FORMA DI DRAGO! <PH>", "." },
  ["1429bee9bf477d64"] = { "Viviamo solo per servire l'antico. MUORI, <INTRUSO/INTRUSA>!", "." },
  ["143bee3c349605ba"] = { "Mi sa proprio che è passato un bel pezzo dall'ultima volta che qualcuno mi ha dato il cambio.", "." },
  ["143d34b814853f03"] = { "Resto qui finché non pesco una cernia da 68 libbre! Tu invece vuoi volare da qualche parte, dico bene?", "." },
  ["143d5bf9849bcf6f"] = { "Per il re!", "." },
  ["143e1562591f1169"] = { "Fermi... devo riprendere.... fiato.", "." },
  ["144312a77213b0bf"] = { "Salute, {class}. Sei <il/la> <benvenuto/benvenuta> a ⟦Nighthaven=Nottequieta⟧ e in tutta ⟦Moonglade=Radaluna⟧. Il ⟦Cenarion Circle=Circolo Cenariano⟧ accoglie tutti gli esseri che rispettano l'autorità e il comando della natura.\n\nFinché sei qui, assicurati di preservare l'equilibrio in ogni cosa. I disordini non sono graditi, e i nostri guardiani sono addestrati a porre fine a ogni ostilità senza esitare.", "." },
  ["1445497364047d2a"] = { "Un'alimentazione adeguata tiene in vita un soldato molto dopo che le ferite del campo di battaglia avrebbero dovuto <finirlo/finirla>, {class}. Se vogliamo resistere nella Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧ che ci attende, ci serviranno tutte le provviste che riusciamo a trasportare. Qui sto raccogliendo pinnagialla maculati prima che vengano spediti.\n\nAl momento ne abbiamo $2101w, ma dobbiamo raccoglierne in tutto $2103w se vogliamo riuscire a sfamare tutti.", "." },
  ["144737510c5e4be7"] = { "Hai più fegato che cervello, se vieni da me senza la preparazione adeguata. Va' a parlare con qualcuno più vicino al tuo livello, come l'orco Kamari, che abita nel Drag di Orgrimmar.", "." },
  ["14527471c39d949d"] = { "I draghi blu non sono qui di persona, ma i seguaci di Malygos sì. Non so perché, ma una cosa posso dirtela: dove ci sono i draghi blu, aspettati di trovare la magia arcana. Non mi sorprenderebbe se le dragobestie fossero qui a proteggere qualcosa... forse qualcosa che gli ⟦Highborne=Alti Nobili⟧ si sono lasciati alle spalle.", "." },
  ["1452ffc8c7a93f97"] = { "Il sangue di %s schizza in aria!", "." },
  ["1455f28b083f3d2b"] = { "A quanto pare dovrò intervenire e occuparmi di te personalmente.", "." },
  ["145f1261f5cff181"] = { "Salve, Antonio. Che piacere vedere che sei arrivato di nuovo sano e salvo. Fammi sapere se ti serve qualcosa.", "." },
  ["145fe5e84af0ee26"] = { "Ti addestrerei se potessi, ma ti serve qualcuno un po' più... com'è che si dice? Cervellone! Cerca Trixie Quickswitch a ⟦Ironforge=Forgiardente⟧. Dille che ti manda Bronk!", "." },
  ["1462899e04f75945"] = { "Abbiamo vinto $2219W battaglie contro il Flagello. Preparati, {name}, perché questa guerra è tutt'altro che finita.", "." },
  ["14694a19b5e6be04"] = { "<Sicuro/Sicura> di non voler imparare a fare <il/la> <guerriero/guerriera>? Beh, è la tua pelle sul campo di battaglia. Se vuoi davvero imparare ad agitare il ditino, faresti meglio a parlare con ⟦Magis Sparkmantle=Magis Frizzamanto⟧ nella ⟦Thunderbrew Distillery=Distilleria Birratuono⟧.", "." },
  ["146ccd94ccabc8e0"] = { "Come posso aiutarti, <signore/signora>?", "." },
  ["14724c4354957f8a"] = { "L'unico {race} buono è un {race} morto!", "." },
  ["1476692ed667b84c"] = { "Prendi questo! I Baffosecco vinceranno!", "." },
  ["1478e1889c68a0b0"] = { "Presto! {name} attacca!", "." },
  ["147d4137ca0b2477"] = { "Che il tuo spirito arda luminoso, {name}.", "." },
  ["148d2d1534e7dabc"] = { "Cosa sai dirmi della situazione dei Windshapers?", "." },
  ["14a3bbb65795619a"] = { "Che Cenarius vegli su di te, <fratello/sorella>.\n\nSono Tajarri e ho giurato di proteggere questo santuario. È un onore per me servire il custode Remulos, vegliando su questa terra sacra.", "." },
  ["14acf86805a68210"] = { "E grazie a te, {name}. Senza il tuo aiuto forse non avrei mai trovato la strada per raggiungere i Reietti.", "." },
  ["14b160668350d72d"] = { "Ehi, Bly! Bilgewizzle rivuole la sua bacchetta divino-matica!", "." },
  ["14b59e336e3a024e"] = { "Ma qualcosa è andato storto, vero?", "." },
  ["14bf49ad1421bdd9"] = { "Mio padre dice che è solo una storia.", "." },
  ["14bfce19a57454a4"] = { "Quanti dei nostri luogotenenti sono ancora vivi, Vanndar?", "." },
  ["14c07581a22807cf"] = { "Sei mio, maldestriero! Ora il tuo spirito è legato a me!", "." },
  ["14c61c47430c3f7f"] = { "Allora è meglio che ti sieda, sarà una storia lunga.\n\nQuando arrivammo a ⟦Silithus=Silitus⟧, la signora Mar'alith fu la prima degli elfi della notte della ⟦Cenarion Hold=Fortezza Cenariana⟧ a unirsi alla spedizione. La nostra routine non aveva nulla di straordinario: formare un gruppo, avventurarsi nei vari alveari e cercare manufatti perduti.", "." },
  ["14ca0a0a5e14f3b8"] = { "I Creatori usano la visitazione come mezzo per ristabilire il controllo sui mondi inseminati quando forze, esterne e interne, alterano le dinamiche della matrice a essi associata. Tali tattiche non vanno prese alla leggera quando vengono attuate dai Creatori.\n\nPer ulteriori informazioni sulla visitazione programmata di questo mondo, consulta l'archivio dati competente che gestisce tutte le questioni di programmazione relative ai Creatori.", "." },
  ["14cae8baec438061"] = { "%s scatena una burrasca che spazza la terra; il suono della sua furia cieca arriva da nord-ovest.", "." },
  ["14cb7f48b4949a38"] = { "Devo dire che ⟦Booty Bay=Baia del Bottino⟧ ha il miglior ⟦Clam Chowder=Guazzetto di Bivalve⟧ di tutti i ⟦South Seas=Mari del Sud⟧. Oh, la cucina non ti interessa, eh? Allora ti do subito il benvenuto all'ormeggio della Maiden's Fancy, la miglior nave passeggeri che viaggi tra i Regni Orientali e Kalimdor. Dovrebbe tornare presto per un altro viaggio verso ⟦Ratchet=Porto Paranco⟧, quindi mettiti <comodo/comoda> finché non arriva.", "." },
  ["14d2a0804c413cc4"] = { "Guidare un carro a vapore non è per tutti. Ci vogliono una presa di ferro e nervi d'acciaio... per fortuna li ho entrambi! E tu? Di che pasta sei <fatto/fatta>? Vuoi dimostrarmelo?", "." },
  ["14db7dfcfac6f1b1"] = { "Il culto degli Al'Aketh rappresenta il pericolo più diretto e urgente per la nostra patria. Le loro azioni sempre più estremiste hanno destabilizzato la nostra società e danneggiato il nostro legame, già indebolito, con gli spiriti dei quattro venti. Gli elementi esigono un'azione che dimostri la nostra tenacia e la nostra determinazione, qualità proprie del dominio dell'elemento della terra.", "." },
  ["14e4f1f5a1458a7a"] = { "È ora che la carovana di Gizleton si rimetta in viaggio! Torneremo presto, ma se non puoi aspettare, vai a nord fino al ⟦Kormek's Hut=Capanno di Kormek⟧. Apriamo bottega tra circa un'ora.", "." },
  ["14ea81a8bdab91df"] = { "Si chiama Rupert Boch. Ho sentito che è al piano di sopra, in una delle stanze della ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, nella parte sud-orientale della città.", "." },
  ["14f0461cfe7fb2b0"] = { "La terra custodisce molti segreti, {class}; è nostro dovere fare in modo che quelli che devono restare segreti per il bene di tutti restino tali.", "." },
  ["14f4a7910bae917a"] = { "Questa resistenza continua e fastidiosa è inutile, vermi! Alla fine non ci sarà altro che morte!", "." },
  ["14f932c031f85f2c"] = { "Che... freddo...", "." },
})
